var Q5 = [
{n:1, q:'El Poder Judicial en España está regulado en la Constitución en:', o:{a:'El Título V.',b:'El Título VI.',c:'El Título VII.',d:'El Título VIII.'}, correct:'a', why:{a:'El Poder Judicial está regulado en el Título VI de la Constitución Española de 1978, artículos 117 a 127.'}},
{n:2, q:'La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados:', o:{a:'Independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.',b:'Independientes, inamovibles e irresponsables.',c:'Dependientes del Gobierno y sometidos a la ley.',d:'Independientes y responsables ante el Ministerio de Justicia.'}, correct:'d', why:{d:'El art.117.1 CE establece que la justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.'}},
{n:3, q:'El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales. Sin embargo, se reconoce la jurisdicción militar:', o:{a:'En todo tipo de causas.',b:'Solo durante los estados de alarma, excepción y sitio.',c:'En el ámbito estrictamente castrense y en los supuestos de estado de sitio, de acuerdo con los principios de la Constitución.',d:'Nunca, ya que la CE prohíbe los Tribunales especiales.'}, correct:'c', why:{c:'El art.117.5 CE establece que el principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales, reconociéndose la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio.'}},
{n:4, q:'¿Cuál de los siguientes es un principio del ejercicio de la potestad jurisdiccional?', o:{a:'Concentración.',b:'Exclusividad.',c:'Economía procesal.',d:'Acumulación.'}, correct:'c', why:{c:'El art.117.3 CE establece que el ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes.'}},
{n:5, q:'Los Jueces y Magistrados de carrera forman un cuerpo único y se rigen por el Estatuto de la carrera judicial. Podrán ser suspendidos:', o:{a:'Por el Ministerio de Justicia.',b:'Solo por el Consejo General del Poder Judicial.',c:'Por el Gobierno, en casos excepcionales.',d:'Solo en los casos y con las garantías previstas en la ley.'}, correct:'b', why:{b:'El art.117.2 CE establece que los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en la ley.'}},
{n:6, q:'Se prohíben los Tribunales de excepción. Sin embargo, están permitidos:', o:{a:'Los Tribunales militares.',b:'Los Tribunales de honor en el ámbito civil.',c:'Los Tribunales consuetudinarios y tradicionales.',d:'Ningún tipo de Tribunal especial.'}, correct:'d', why:{d:'El art.117.6 CE prohíbe los Tribunales de excepción. Sin embargo, el art.125 CE reconoce la jurisdicción de los Tribunales consuetudinarios y tradicionales como el Tribunal de las Aguas de la Vega Valenciana.'}},
{n:7, q:'Según la CE, los ciudadanos podrán ejercer la acción popular:', o:{a:'Solo en causas penales.',b:'En todos los procesos judiciales.',c:'En los casos y formas establecidos por la ley.',d:'Solo para defender sus derechos individuales.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:8, q:'El Consejo General del Poder Judicial está integrado por:', o:{a:'El Presidente del Tribunal Supremo y 12 vocales.',b:'El Presidente del Tribunal Supremo y 20 vocales.',c:'El Presidente del Tribunal Supremo y 16 vocales.',d:'Solo los Presidentes de los Tribunales Superiores de Justicia.'}, correct:'a', why:{a:'El art.122.3 CE establece que el CGPJ estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años.'}},
{n:9, q:'Los vocales del CGPJ son nombrados por el Rey a propuesta de:', o:{a:'El Gobierno.',b:'El Congreso y el Senado.',c:'El Tribunal Supremo.',d:'Los Jueces y Magistrados.'}, correct:'a', why:{a:'El art.122.3 CE establece que los 20 miembros del CGPJ serán nombrados por el Rey, doce entre Jueces y Magistrados de todas las categorías judiciales y ocho entre abogados y otros juristas, todos propuestos por el Congreso y el Senado.'}},
{n:10, q:'El mandato de los vocales del CGPJ es de:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Indefinido.'}, correct:'b', why:{b:'El art.122.3 CE establece que los miembros del CGPJ son nombrados por el Rey por un período de cinco años.'}},
{n:11, q:'El Tribunal Supremo tiene jurisdicción en toda España y es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de:', o:{a:'Garantías constitucionales.',b:'Derecho penal.',c:'Derecho civil.',d:'Derechos fundamentales.'}, correct:'b', why:{b:'El art.123.1 CE establece que el Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales.'}},
{n:12, q:'Los Tribunales Superiores de Justicia de las Comunidades Autónomas:', o:{a:'Solo tienen competencia en materia civil.',b:'Culminan la organización judicial en el ámbito de la Comunidad Autónoma.',c:'Dependen del Tribunal Supremo directamente.',d:'Son presididos por el Presidente de la CCAA.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:13, q:'¿Cuántas Salas tiene el Tribunal Supremo?', o:{a:'Tres.',b:'Cuatro.',c:'Cinco.',d:'Seis.'}, correct:'c', why:{c:'El Tribunal Supremo se organiza en cinco Salas: de lo Civil, de lo Penal, de lo Contencioso-Administrativo, de lo Social y de lo Militar.'}},
{n:14, q:'El Ministerio Fiscal:', o:{a:'Forma parte del Poder Judicial.',b:'Promueve la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público.',c:'Depende del CGPJ.',d:'Es nombrado por el Tribunal Supremo.'}, correct:'d', why:{d:'El art.124 CE establece que el Ministerio Fiscal, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley.'}},
{n:15, q:'El Fiscal General del Estado es nombrado por:', o:{a:'El CGPJ.',b:'Las Cortes Generales.',c:'El Rey, a propuesta del Gobierno, oído el CGPJ.',d:'El Tribunal Supremo.'}, correct:'c', why:{c:'El art.124.4 CE establece que el Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial.'}},
{n:16, q:'El Tribunal Constitucional se regula en la CE en:', o:{a:'El Título VIII.',b:'El Título IX.',c:'El Título X.',d:'El Título VI.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:17, q:'El Tribunal Constitucional se compone de:', o:{a:'9 miembros.',b:'12 miembros.',c:'15 miembros.',d:'21 miembros.'}, correct:'a', why:{a:'El art.159.1 CE establece que el Tribunal Constitucional se compone de 12 miembros nombrados por el Rey.'}},
{n:18, q:'Los miembros del Tribunal Constitucional son nombrados por el Rey a propuesta de:', o:{a:'Solo el Congreso de los Diputados.',b:'El Congreso (4), el Senado (4), el Gobierno (2) y el CGPJ (2).',c:'El Gobierno (6) y las Cortes (6).',d:'El Congreso (6) y el Senado (6).'}, correct:'d', why:{d:'El art.159.1 CE establece que los 12 miembros del TC son propuestos: 4 por el Congreso, 4 por el Senado, 2 por el Gobierno y 2 por el CGPJ.'}},
{n:19, q:'El mandato de los miembros del Tribunal Constitucional es de:', o:{a:'Seis años.',b:'Nueve años.',c:'Doce años.',d:'Indefinido.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:20, q:'Los miembros del Tribunal Constitucional son inamovibles durante su mandato. Podrán ser cesados:', o:{a:'Por el Gobierno en casos graves.',b:'Por el Congreso por mayoría absoluta.',c:'Por expiración de su mandato, renuncia, fallecimiento o incapacidad o por incurrir en causa de incompatibilidad.',d:'Por el CGPJ.'}, correct:'b', why:{b:'Los miembros del TC pueden cesar por expiración del mandato, renuncia, incapacidad sobrevenida, incompatibilidad o condena por delito doloso.'}},
{n:21, q:'El Tribunal Constitucional tiene jurisdicción en:', o:{a:'Solo en Madrid.',b:'Todo el territorio español.',c:'El ámbito de la Comunidad Autónoma de residencia.',d:'El ámbito de aplicación de la Constitución Española.'}, correct:'d', why:{d:'El art.161 CE establece que el Tribunal Constitucional tiene jurisdicción en todo el territorio español.'}},
{n:22, q:'El recurso de inconstitucionalidad puede ser interpuesto por:', o:{a:'Cualquier ciudadano.',b:'El Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores o los órganos colegiados ejecutivos de las CCAA.',c:'Solo el Gobierno.',d:'Solo el CGPJ.'}, correct:'b', why:{b:'El art.162.1.a CE establece que están legitimados para interponer el recurso de inconstitucionalidad el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las CCAA y las Asambleas de las mismas.'}},
{n:23, q:'El recurso de amparo constitucional puede ser interpuesto por:', o:{a:'Solo los ciudadanos españoles.',b:'Cualquier persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal.',c:'Solo el Gobierno.',d:'Solo las personas físicas, no las jurídicas.'}, correct:'c', why:{c:'El art.162.1.b CE establece que están legitimados para interponer el recurso de amparo toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.'}},
{n:24, q:'¿Cuál es el plazo para interponer el recurso de inconstitucionalidad?', o:{a:'Un mes desde la publicación de la ley.',b:'Tres meses desde la publicación de la ley.',c:'Seis meses desde la publicación de la ley.',d:'Un año desde la publicación de la ley.'}, correct:'b', why:{b:'La LOTC establece que el recurso de inconstitucionalidad se interpondrá dentro de los tres meses siguientes a la publicación de la ley, disposición normativa o acto con fuerza de ley impugnados.'}},
{n:25, q:'La cuestión de inconstitucionalidad puede ser planteada por:', o:{a:'Cualquier ciudadano durante un proceso judicial.',b:'Los Jueces y Tribunales cuando consideren que una norma con rango de ley aplicable al proceso es inconstitucional.',c:'El Ministerio Fiscal en cualquier momento.',d:'El Gobierno ante cualquier Tribunal.'}, correct:'a', why:{a:'El art.163 CE establece que cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Constitucional.'}},
{n:26, q:'Las sentencias del Tribunal Constitucional:', o:{a:'Tienen valor de cosa juzgada pero no vinculan a todos.',b:'Solo vinculan a las partes del proceso.',c:'Tienen plenos efectos frente a todos.',d:'Solo pueden ser impugnadas ante el Tribunal Supremo.'}, correct:'c', why:{c:'El art.164.1 CE establece que las sentencias del TC que declaren la inconstitucionalidad de una ley o de una norma con fuerza de ley tienen plenos efectos frente a todos.'}},
{n:27, q:'¿Qué es el conflicto de competencias entre el Estado y las Comunidades Autónomas?', o:{a:'Un proceso ante el Tribunal Supremo.',b:'Un proceso ante el Tribunal Constitucional.',c:'Un proceso ante el Senado.',d:'Un proceso ante el Consejo de Estado.'}, correct:'d', why:{d:'Los conflictos de competencias entre el Estado y las CCAA o entre las propias CCAA son resueltos por el Tribunal Constitucional (art.161.1.c CE).'}},
{n:28, q:'La declaración del estado de alarma compete a:', o:{a:'El Congreso de los Diputados.',b:'El Gobierno mediante decreto acordado en Consejo de Ministros.',c:'El Rey.',d:'El Presidente del Gobierno.'}, correct:'b', why:{b:'El art.116.2 CE establece que el estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días.'}},
{n:29, q:'La declaración del estado de excepción corresponde a:', o:{a:'El Gobierno, previa autorización del Congreso.',b:'El Rey, a propuesta del Gobierno.',c:'Las Cortes Generales.',d:'El Congreso directamente.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:30, q:'El estado de sitio es declarado por:', o:{a:'El Gobierno.',b:'El Presidente del Gobierno.',c:'El Congreso de los Diputados por mayoría absoluta.',d:'El Rey.'}, correct:'c', why:{c:'El art.116.4 CE establece que el estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno.'}},
{n:31, q:'Durante el estado de alarma NO se pueden suspender los derechos reconocidos en la CE. Durante el estado de excepción SÍ pueden suspenderse algunos derechos. ¿Cuántos y cuáles?', o:{a:'Solo el derecho de huelga.',b:'Solo la libertad de circulación.',c:'Los previstos en los artículos 17, 18.2 y 3, 19, 20.1.a y d, y 5, 21, 28.2 y 37.2.',d:'Todos los derechos fundamentales.'}, correct:'c', why:{c:'El art.55 CE establece que durante el estado de excepción podrán suspenderse los derechos reconocidos en los arts. 17, 18.2 y 3, 19, 20.1.a y d, y 5, 21, 28.2 y 37.2 CE.'}},
{n:32, q:'La duración máxima del estado de alarma en su declaración inicial es de:', o:{a:'7 días.',b:'15 días.',c:'30 días.',d:'3 meses.'}, correct:'c', why:{c:'El art.116.2 CE establece que el estado de alarma será declarado por el Gobierno por un plazo máximo de quince días, dando cuenta al Congreso, que deberá quedar reunido durante todo el período de vigencia.'}},
{n:33, q:'¿Puede prorrogarse el estado de alarma?', o:{a:'No, en ningún caso.',b:'Sí, sin límite de prórrogas, por el Gobierno.',c:'Sí, con autorización del Congreso.',d:'Sí, pero solo una vez y por otros 15 días.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:34, q:'Durante la vigencia del estado de excepción o sitio, el Congreso NO podrá ser:', o:{a:'Convocado en sesión extraordinaria.',b:'Disuelto.',c:'Interpelado.',d:'Prorrogado en sus sesiones.'}, correct:'a', why:{a:'El art.116.5 CE establece que no podrá procederse a la disolución del Congreso mientras estén declarados algunos de los estados contemplados en el artículo 116.'}},
{n:35, q:'La jurisdicción ordinaria en España se divide en cuatro órdenes:', o:{a:'Civil, penal, contencioso-administrativo y social.',b:'Civil, mercantil, penal y social.',c:'Civil, penal, militar y contencioso-administrativo.',d:'Constitucional, civil, penal y administrativo.'}, correct:'a', why:{a:'La jurisdicción ordinaria en España se divide en cuatro órdenes: civil, penal, contencioso-administrativo y social, conforme a la LOPJ.'}},
{n:36, q:'Los Juzgados de Primera Instancia pertenecen al orden:', o:{a:'Penal.',b:'Civil.',c:'Contencioso-administrativo.',d:'Social.'}, correct:'b', why:{b:'Los Juzgados de Primera Instancia son órganos de la jurisdicción civil, que conocen en primera instancia de los asuntos civiles.'}},
{n:37, q:'Los Juzgados de lo Penal:', o:{a:'Son competentes para delitos graves.',b:'Conocen de los juicios orales por delitos cuya pena privativa de libertad no excede de cinco años.',c:'Solo conocen de faltas.',d:'Son órganos de apelación de los Juzgados de Instrucción.'}, correct:'b', why:{b:'Los Juzgados de lo Penal conocen de los juicios orales por delitos castigados con penas que no exceden de cinco años de privación de libertad u otras penas de distinta naturaleza.'}},
{n:38, q:'El Tribunal del Jurado juzga:', o:{a:'Todos los delitos graves.',b:'Solo los delitos políticos.',c:'Los delitos que la ley determine.',d:'Solo los delitos contra la vida.'}, correct:'c', why:{c:'El art.125 CE reconoce la participación de los ciudadanos en la Administración de Justicia mediante la institución del Jurado, en los casos y con las formas que la ley establezca.'}},
{n:39, q:'¿Qué órgano jurisdiccional es competente para conocer de los recursos de casación en materia civil?', o:{a:'Los Tribunales Superiores de Justicia.',b:'Las Audiencias Provinciales.',c:'El Tribunal Supremo (Sala de lo Civil).',d:'La Audiencia Nacional.'}, correct:'a', why:{a:'La Sala de lo Civil del Tribunal Supremo es el órgano competente para conocer de los recursos de casación en materia civil.'}},
{n:40, q:'La Audiencia Nacional tiene competencia en:', o:{a:'Todo el territorio español en determinados delitos.',b:'Solo la Comunidad de Madrid.',c:'Los delitos cometidos en el extranjero por españoles.',d:'Los delitos militares.'}, correct:'d', why:{d:'La Audiencia Nacional tiene competencia en todo el territorio español para determinados delitos de especial gravedad o trascendencia, como terrorismo, tráfico de drogas a gran escala, delitos económicos y otros.'}},
{n:41, q:'El principio de publicidad en el proceso judicial:', o:{a:'Permite que todos los actos procesales sean públicos sin excepción.',b:'Puede limitarse para proteger el orden público, la seguridad nacional o los derechos fundamentales.',c:'Solo se aplica en el proceso penal.',d:'Solo rige en los juicios orales.'}, correct:'b', why:{b:'El art.120.1 CE establece que las actuaciones judiciales serán públicas, con las excepciones que prevean las leyes de procedimiento.'}},
{n:42, q:'El principio de inmediación judicial exige:', o:{a:'Que el Juez resuelva el asunto en el plazo más breve posible.',b:'Que el Juez que ha presenciado la práctica de las pruebas sea el que dicte sentencia.',c:'Que las partes estén presentes en el juicio.',d:'Que el proceso se desarrolle en el juzgado más cercano al domicilio del demandado.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:43, q:'Según la CE, la justicia gratuita se reconoce:', o:{a:'Solo para los ciudadanos españoles.',b:'A quienes acrediten insuficiencia de recursos económicos.',c:'A todos los ciudadanos.',d:'Solo en el orden penal.'}, correct:'b', why:{b:'El art.119 CE establece que la justicia será gratuita cuando así lo disponga la ley, y en todo caso respecto de quienes acrediten insuficiencia de recursos para litigar.'}},
{n:44, q:'Los Juzgados de Instrucción:', o:{a:'Juzgan los delitos menores.',b:'Realizan la instrucción de las causas penales por delito.',c:'Conocen de los juicios de faltas y delitos leves.',d:'Son órganos de la jurisdicción civil.'}, correct:'c', why:{c:'Los Juzgados de Instrucción instruyen las causas por delito cuyo enjuiciamiento corresponde a las Audiencias Provinciales, y también conocen de los juicios por delito leve.'}},
{n:45, q:'El Ministerio Fiscal actúa con sujeción a los principios de:', o:{a:'Legalidad e imparcialidad.',b:'Unidad de actuación, dependencia jerárquica y sujeción a los principios de legalidad e imparcialidad.',c:'Solo legalidad.',d:'Independencia y objetividad.'}, correct:'d', why:{d:'El art.124.2 CE establece que el Ministerio Fiscal ejerce sus funciones con sujeción a los principios de unidad de actuación, dependencia jerárquica, legalidad e imparcialidad.'}},
{n:46, q:'¿Puede un Juez ser trasladado sin su consentimiento?', o:{a:'Sí, por decisión del Ministerio de Justicia.',b:'Sí, si el CGPJ lo acuerda motivadamente.',c:'No, salvo causa legal prevista en el Estatuto de la carrera judicial.',d:'Sí, cuando lo decidan las Cortes Generales.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:47, q:'¿Qué garantiza el principio de exclusividad jurisdiccional?', o:{a:'Que solo los Jueces puedan aplicar la ley penal.',b:'Que los Jueces y Tribunales determinados por ley sean los únicos que ejerzan la potestad jurisdiccional.',c:'Que cada Juez conozca solo un tipo de asuntos.',d:'Que la justicia sea administrada exclusivamente por funcionarios del Estado.'}, correct:'b', why:{b:'El art.117.3 CE establece que el ejercicio de la potestad jurisdiccional corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes.'}},
{n:48, q:'La Ley Orgánica del Poder Judicial establece los órdenes jurisdiccionales. ¿Cuál de los siguientes NO existe en el sistema español?', o:{a:'Civil.',b:'Penal.',c:'Constitucional.',d:'Social.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:49, q:'Los Juzgados de lo Contencioso-Administrativo:', o:{a:'Conocen de los recursos contra actos de las grandes Administraciones.',b:'Conocen de recursos contra actos de las Administraciones locales y de las CCAA en primera instancia.',c:'Son competentes solo en materia tributaria.',d:'Dependen del Tribunal Supremo.'}, correct:'c', why:{c:'Los Juzgados de lo Contencioso-Administrativo conocen en primera instancia de los recursos contra actos de las Entidades locales y de la Administración autonómica, entre otros.'}},
{n:50, q:'El Tribunal Constitucional NO puede conocer de:', o:{a:'Recursos de inconstitucionalidad.',b:'Recursos de amparo.',c:'Conflictos entre órganos constitucionales del Estado.',d:'Recursos de casación civil.'}, correct:'d', why:{d:'El recurso de casación civil es competencia de la Sala de lo Civil del Tribunal Supremo, no del Tribunal Constitucional. El TC conoce de los recursos de inconstitucionalidad, de amparo, de conflictos de competencia y de otros supuestos constitucionales.'}},
{n:51, q:'¿Qué es el habeas corpus?', o:{a:'Un recurso constitucional para proteger la libertad personal frente a detenciones ilegales.',b:'Un recurso ante el Tribunal Supremo.',c:'Una acción popular en el proceso penal.',d:'Un recurso de amparo constitucional.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:52, q:'El habeas corpus es regulado en la CE en el artículo:', o:{a:'Art. 17.4.',b:'Art. 24.2.',c:'Art. 53.2.',d:'Art. 55.1.'}, correct:'a', why:{a:'El art.17.4 CE establece que la ley regulará un procedimiento de habeas corpus para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.'}},
{n:53, q:'La tutela judicial efectiva está reconocida en el art.24 CE. Este derecho incluye:', o:{a:'El derecho a un proceso sin dilaciones indebidas.',b:'El derecho a la asistencia de letrado.',c:'El derecho a utilizar los medios de prueba pertinentes.',d:'Todos los anteriores.'}, correct:'d', why:{d:'El art.24 CE recoge el derecho a la tutela judicial efectiva, que incluye el derecho a obtener tutela de los Jueces sin indefensión, a un proceso sin dilaciones indebidas, a usar los medios de prueba y a la presunción de inocencia.'}},
{n:54, q:'El principio de presunción de inocencia implica:', o:{a:'Que el acusado no tiene que probar su inocencia.',b:'Que el Juez debe absolver siempre.',c:'Que la carga de la prueba corresponde a la defensa.',d:'Que los delitos se prescriben automáticamente.'}, correct:'a', why:{a:'El art.24.2 CE reconoce el derecho a la presunción de inocencia, que implica que toda persona acusada se presume inocente hasta que se pruebe su culpabilidad mediante prueba de cargo suficiente obtenida con todas las garantías.'}},
{n:55, q:'Según la CE, el Consejo General del Poder Judicial es el órgano de gobierno del Poder Judicial. Su regulación se establece mediante:', o:{a:'La propia Constitución.',b:'Ley orgánica.',c:'Real decreto.',d:'La Ley del Poder Judicial ordinaria.'}, correct:'a', why:{a:'El art.122.2 CE establece que el CGPJ es el órgano de gobierno del mismo, y su régimen jurídico, tanto en lo relativo a su composición como a su estatuto y régimen de incompatibilidades de sus miembros, será establecido por ley orgánica.'}},
{n:56, q:'El Tribunal Supremo es el órgano jurisdiccional superior en todos los órdenes salvo en materia constitucional. ¿Quién lo preside?', o:{a:'El Ministro de Justicia.',b:'El Presidente del CGPJ, que también preside el Tribunal Supremo.',c:'Un magistrado elegido por sus pares.',d:'El Rey.'}, correct:'d', why:{d:'El Presidente del Tribunal Supremo es nombrado por el Rey, a propuesta del CGPJ, conforme al art.123.2 CE.'}},
{n:57, q:'Las resoluciones judiciales pueden ser:', o:{a:'Providencias, autos y sentencias.',b:'Solo sentencias y autos.',c:'Providencias, autos, sentencias y decretos.',d:'Solo sentencias.'}, correct:'c', why:{c:'Las resoluciones judiciales son providencias, autos y sentencias conforme a la LOPJ y las leyes procesales.'}},
{n:58, q:'La acción penal en España es:', o:{a:'Privada, ejercida exclusivamente por la víctima.',b:'Pública, pudiendo ser ejercida por el Ministerio Fiscal y cualquier ciudadano.',c:'Solo ejercida por el Ministerio Fiscal.',d:'Solo ejercida por el acusado particular.'}, correct:'b', why:{b:'En España la acción penal puede ser ejercida por el Ministerio Fiscal (acción pública), por el perjudicado (acción particular) y por cualquier ciudadano (acción popular), conforme al art.125 CE y la LECrim.'}},
{n:59, q:'¿Cuál es el órgano competente para conocer del recurso de amparo en primera instancia?', o:{a:'El Tribunal Supremo.',b:'El Tribunal Superior de Justicia.',c:'El Tribunal Constitucional.',d:'La Audiencia Nacional.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:60, q:'El Ministerio Fiscal es único para todo el Estado pero actúa a través de órganos propios. ¿Cuál es el órgano superior?', o:{a:'La Fiscalía General del Estado.',b:'La Fiscalía del Tribunal Supremo.',c:'La Fiscalía de la Audiencia Nacional.',d:'La Junta de Fiscales.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:61, q:'El Defensor del Pueblo es el alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos comprendidos en el Título I. ¿Puede interponer recurso de amparo?', o:{a:'No, nunca.',b:'Sí, siempre.',c:'Sí, está legitimado para interponer recurso de amparo y de inconstitucionalidad.',d:'Solo puede actuar en materia administrativa.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:62, q:'El principio de oralidad en el proceso judicial exige:', o:{a:'Que todas las actuaciones se hagan de palabra.',b:'Que el proceso se desarrolle verbalmente y que el Juez que ha presenciado las pruebas dicte la sentencia.',c:'Que las partes se expresen en castellano.',d:'Que el Juez dicte la sentencia oralmente.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:63, q:'El recurso de casación ante el Tribunal Supremo en materia penal procede contra:', o:{a:'Todas las sentencias penales.',b:'Las sentencias dictadas en segunda instancia por las Audiencias.',c:'Solo las sentencias del Tribunal del Jurado.',d:'Las sentencias dictadas por los Juzgados de lo Penal.'}, correct:'b', why:{b:'El recurso de casación penal ante la Sala Segunda del Tribunal Supremo procede contra las sentencias dictadas por las Audiencias Provinciales o la Audiencia Nacional en segunda instancia.'}},
{n:64, q:'¿Qué significa que los Jueces y Magistrados son responsables?', o:{a:'Que pueden ser procesados por sus actuaciones judiciales.',b:'Que responden civil, penal y disciplinariamente por los daños causados en el ejercicio de sus funciones con dolo, culpa o ignorancia inexcusable.',c:'Que son responsables ante el CGPJ de sus resoluciones.',d:'Que pueden ser destituidos por el Gobierno.'}, correct:'b', why:{b:'La responsabilidad de los Jueces y Magistrados comprende la responsabilidad civil, penal y disciplinaria por los daños causados en el ejercicio de sus funciones dolosa o culpablemente.'}},
{n:65, q:'¿Quién puede plantear un conflicto de competencias ante el Tribunal Constitucional?', o:{a:'Cualquier ciudadano.',b:'El Gobierno del Estado y los órganos ejecutivos de las CCAA.',c:'Solo el Gobierno central.',d:'Las Cortes Generales.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:66, q:'Las Salas del Tribunal Constitucional están compuestas por:', o:{a:'4 magistrados cada una.',b:'5 magistrados cada una.',c:'6 magistrados cada una.',d:'7 magistrados cada una.'}, correct:'c', why:{c:'El TC se organiza en dos Salas, cada una compuesta por seis magistrados, y en Secciones compuestas por tres magistrados.'}},
{n:67, q:'El Presidente del Tribunal Constitucional es nombrado por:', o:{a:'El Rey, a propuesta de los propios magistrados del TC.',b:'Las Cortes Generales.',c:'El Gobierno.',d:'El CGPJ.'}, correct:'a', why:{a:'El Presidente del TC es elegido por los propios magistrados del TC en pleno y nombrado por el Rey.'}},
{n:68, q:'¿Cuánto dura el mandato del Presidente del Tribunal Constitucional?', o:{a:'3 años, renovable una sola vez.',b:'4 años, no renovable.',c:'3 años, renovable.',d:'9 años, como el resto de los magistrados.'}, correct:'a', why:{a:'El Presidente del TC es elegido por un período de tres años, con posibilidad de una sola reelección.'}},
{n:69, q:'La LOPJ establece que el Poder Judicial se organiza en las siguientes instancias o grados:', o:{a:'Juzgados de Primera Instancia, Audiencias Provinciales y Tribunal Supremo.',b:'Juzgados, Audiencias Provinciales, Tribunales Superiores de Justicia, Audiencia Nacional y Tribunal Supremo.',c:'Juzgados y Tribunales de segunda instancia.',d:'Solo Juzgados y Tribunal Supremo.'}, correct:'b', why:{b:'La LOPJ organiza los órganos jurisdiccionales en: Juzgados, Audiencias Provinciales, Tribunales Superiores de Justicia, Audiencia Nacional y Tribunal Supremo.'}},
{n:70, q:'Los Juzgados de Paz:', o:{a:'Son órganos de la jurisdicción penal.',b:'Existen en municipios que no son capital de partido judicial y ejercen funciones de jurisdicción civil y registro civil.',c:'Tienen competencias en materia contencioso-administrativa.',d:'Dependen directamente del Tribunal Supremo.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:71, q:'El principio de contradicción en el proceso exige:', o:{a:'Que siempre haya acusación y defensa.',b:'Que las partes puedan alegar y probar todo lo que estimen conveniente a su derecho.',c:'Que el Juez dicte sentencia en contra del demandado.',d:'Que el proceso sea oral.'}, correct:'a', why:{a:'El principio de contradicción garantiza que ninguna parte pueda ser condenada sin ser oída y vencida en juicio, permitiendo a todas las partes alegar y probar lo que estimen conveniente.'}},
{n:72, q:'¿Qué es la legitimación procesal activa?', o:{a:'El derecho de toda persona a ser parte en un proceso.',b:'La facultad de promover una actuación jurisdiccional por ser titular del derecho subjetivo o interés legítimo.',c:'El derecho del acusado a ser asistido por letrado.',d:'La capacidad del Juez para conocer del asunto.'}, correct:'a', why:{a:'La legitimación procesal activa es la facultad de promover una actuación jurisdiccional por ser titular del derecho subjetivo o interés legítimo que se pretende proteger.'}},
{n:73, q:'Las Secciones del Tribunal Constitucional se componen de:', o:{a:'2 magistrados.',b:'3 magistrados.',c:'4 magistrados.',d:'6 magistrados.'}, correct:'c', why:{c:'Las Secciones del TC están compuestas por tres magistrados, y conocen principalmente de la admisión o inadmisión a trámite de los recursos.'}},
{n:74, q:'El Tribunal Constitucional puede declarar la inconstitucionalidad de una norma con efecto:', o:{a:'Solo ex nunc (desde el momento de la sentencia).',b:'Ex tunc (retroactivo) en todos los casos.',c:'Ex nunc en general, pero puede modular los efectos en el tiempo.',d:'Solo inter partes.'}, correct:'c', why:{c:'La declaración de inconstitucionalidad por el TC tiene efectos ex nunc como regla general, aunque el TC puede modular los efectos temporales de sus sentencias, limitando la retroactividad.'}},
{n:75, q:'¿Qué órgano es competente para enjuiciar los delitos cometidos por los aforados?', o:{a:'El Juzgado de Instrucción del domicilio del aforado.',b:'La Audiencia Provincial.',c:'El Tribunal Superior de Justicia o el Tribunal Supremo, según el caso.',d:'La Audiencia Nacional.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:76, q:'El Jurado popular en España está compuesto por:', o:{a:'12 jurados y 2 suplentes.',b:'9 jurados y 2 suplentes.',c:'9 jurados y 3 suplentes.',d:'12 jurados y 3 suplentes.'}, correct:'c', why:{c:'La Ley Orgánica del Tribunal del Jurado establece que el Tribunal del Jurado estará compuesto por nueve jurados y un Magistrado-Presidente, más dos jurados suplentes.'}},
{n:77, q:'El Tribunal Constitucional puede suspender la aplicación de la norma impugnada:', o:{a:'Solo en el recurso de inconstitucionalidad, automáticamente.',b:'Solo en el recurso de amparo.',c:'En determinados supuestos previstos en la LOTC, de forma motivada.',d:'Nunca puede suspender normas.'}, correct:'c', why:{c:'La LOTC prevé la posibilidad de suspensión cautelar de la norma impugnada en determinados supuestos, como cuando el Gobierno impugna disposiciones de las CCAA (art.161.2 CE).'}},
{n:78, q:'Las sentencias dictadas por el Tribunal Constitucional:', o:{a:'Pueden ser recurridas ante el Tribunal Supremo.',b:'Son definitivas e inapelables.',c:'Pueden ser recurridas ante el TJUE.',d:'Pueden ser modificadas por las Cortes Generales.'}, correct:'c', why:{c:'Las sentencias del Tribunal Constitucional son definitivas e inapelables conforme al art.164.1 CE.'}},
{n:79, q:'¿Qué es la recusación en el ámbito judicial?', o:{a:'El acto de pedir la exclusión de un Juez por causa legal.',b:'El recurso contra una sentencia.',c:'La renuncia de un Juez a conocer de un asunto.',d:'La acción de suspender un proceso.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:80, q:'La Audiencia Nacional conoce, entre otros, de los delitos de:', o:{a:'Falsedad documental.',b:'Terrorismo, tráfico de drogas en grandes cantidades y delitos económicos de especial trascendencia.',c:'Solo delitos cometidos en el extranjero.',d:'Homicidio y asesinato en todo el territorio.'}, correct:'b', why:{b:'La Audiencia Nacional conoce de los delitos de terrorismo, tráfico de drogas en grandes cantidades y delitos económicos de especial trascendencia, entre otros.'}},
{n:81, q:'Los Juzgados de lo Social conocen de:', o:{a:'Los conflictos laborales individuales y colectivos.',b:'Solo los despidos.',c:'Los conflictos entre empresas.',d:'Solo la Seguridad Social.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:82, q:'Según la CE, los Juzgados y Tribunales deben motivar sus resoluciones. Este principio se denomina:', o:{a:'Principio de publicidad.',b:'Principio de motivación.',c:'Principio de contradicción.',d:'Principio de proporcionalidad.'}, correct:'b', why:{b:'El art.120.3 CE establece que las sentencias serán siempre motivadas y se pronunciarán en audiencia pública. La motivación de las resoluciones judiciales es una exigencia constitucional vinculada al derecho a la tutela judicial efectiva.'}},
{n:83, q:'¿Quién ejerce la jurisdicción en los territorios en que no existan Juzgados?', o:{a:'Los Tribunales Superiores de Justicia.',b:'Los Jueces de Paz.',c:'El Ministerio de Justicia.',d:'Los Alcaldes.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:84, q:'La demanda en el proceso civil se presenta ante:', o:{a:'El Juzgado de Primera Instancia competente.',b:'El Ministerio de Justicia.',c:'La Audiencia Provincial directamente.',d:'El Tribunal Supremo.'}, correct:'a', why:{a:'En el proceso civil ordinario, la demanda se presenta ante el Juzgado de Primera Instancia territorialmente competente, conforme a la Ley de Enjuiciamiento Civil.'}},
{n:85, q:'El Tribunal Constitucional puede inadmitir un recurso de amparo:', o:{a:'Solo por falta de legitimación.',b:'Cuando sea manifiestamente improcedente, cuando no exista violación de un derecho fundamental o cuando carezca de especial trascendencia constitucional.',c:'Solo cuando haya sido resuelto por el Tribunal Supremo previamente.',d:'Nunca, ya que el derecho al amparo es incondicional.'}, correct:'b', why:{b:'La reforma de la LOTC por LO 6/2007 introdujo la admisión del recurso de amparo solo cuando tenga especial trascendencia constitucional, permitiendo la inadmisión cuando no concurra dicho requisito.'}},
{n:86, q:'El principio acusatorio en el proceso penal implica:', o:{a:'Que el Juez actúa de oficio sin necesidad de acusación.',b:'Que el Juez no puede condenar sin que exista una acusación formulada por parte distinta al propio Juez.',c:'Que el Ministerio Fiscal siempre acusa.',d:'Que la víctima debe acusar necesariamente.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:87, q:'¿Cuál es el recurso procedente contra las sentencias dictadas en primera instancia por los Juzgados de lo Penal?', o:{a:'Recurso de casación.',b:'Recurso de apelación ante la Audiencia Provincial.',c:'Recurso de amparo.',d:'Recurso de revisión.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:88, q:'La ejecución de sentencias corresponde:', o:{a:'Al Ministerio de Justicia.',b:'Al órgano judicial que dictó la sentencia.',c:'Al Gobierno.',d:'Al CGPJ.'}, correct:'c', why:{c:'El art.117.3 CE establece que el ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales. La ejecución es potestad del propio órgano judicial.'}},
{n:89, q:'¿Qué es la cosa juzgada?', o:{a:'Una resolución judicial provisional.',b:'El efecto de firmeza de una sentencia que impide volver a juzgar el mismo asunto.',c:'Una sentencia del Tribunal Supremo.',d:'Una resolución del Tribunal Constitucional.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:90, q:'El recurso extraordinario de revisión procede cuando:', o:{a:'Se ha dictado sentencia injusta.',b:'Existen documentos nuevos que hubieran variado el fallo, se ha condenado por falso testimonio o se ha producido connivencia entre partes.',c:'El Juez ha cometido error en la aplicación del derecho.',d:'El acusado considera excesiva la pena impuesta.'}, correct:'b', why:{b:'El recurso de revisión procede en casos tasados como: aparición de nuevos documentos, condena basada en falso testimonio, doble condena por los mismos hechos u otros supuestos legalmente previstos.'}},
{n:91, q:'El principio de cosa juzgada material impide:', o:{a:'Que el mismo Juez revise su propia sentencia.',b:'Que el mismo hecho sea juzgado dos veces (non bis in idem).',c:'Que la sentencia sea ejecutada.',d:'Que el condenado recurra.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:92, q:'Las resoluciones del Tribunal Constitucional se publican en:', o:{a:'El BOE.',b:'El BOME.',c:'La Gaceta Oficial.',d:'El Diario de Sesiones.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:93, q:'El Tribunal Constitucional puede dictar autos. ¿Para qué se utilizan?', o:{a:'Para resolver el fondo del recurso.',b:'Para resolver cuestiones procesales o incidentales sin resolver el fondo.',c:'Para inadmitir los recursos.',d:'Para dictar medidas cautelares únicamente.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:94, q:'El Tribunal Constitucional en Pleno está formado por:', o:{a:'6 magistrados.',b:'12 magistrados.',c:'Los 12 magistrados que lo componen.',d:'Los Presidentes de Sala y el Presidente del TC.'}, correct:'c', why:{c:'El Pleno del TC está formado por los doce magistrados que integran el Tribunal.'}},
{n:95, q:'¿A qué orden jurisdiccional pertenecen los recursos contra sanciones administrativas?', o:{a:'Civil.',b:'Penal.',c:'Contencioso-administrativo.',d:'Social.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:96, q:'La imparcialidad judicial exige:', o:{a:'Que el Juez no tenga relación con las partes ni con el objeto del litigio.',b:'Que el Juez conozca de todo tipo de asuntos.',c:'Que el Juez sea del mismo lugar que las partes.',d:'Que el Juez no conozca previamente el asunto.'}, correct:'a', why:{a:'La imparcialidad judicial exige que el Juez no tenga vinculación con las partes ni interés en el resultado del litigio, garantizando así la objetividad en su resolución.'}},
{n:97, q:'¿Cuántos vocales del CGPJ son nombrados entre Jueces y Magistrados?', o:{a:'8 vocales.',b:'12 vocales.',c:'10 vocales.',d:'16 vocales.'}, correct:'a', why:{a:'El art.122.3 CE establece que de los 20 vocales del CGPJ, 12 son nombrados entre Jueces y Magistrados de todas las categorías judiciales.'}},
{n:98, q:'¿Qué es el aforamiento?', o:{a:'El privilegio procesal por el que determinadas personas son juzgadas por un órgano jurisdiccional superior al que les correspondería por razón del territorio.',b:'El derecho a recurrir ante el Tribunal Supremo.',c:'La asignación de un Juez específico para un caso.',d:'El derecho a ser juzgado en el propio domicilio.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:99, q:'Las sentencias del Tribunal Constitucional que estimen el amparo:', o:{a:'Declaran la nulidad del acto administrativo impugnado.',b:'Reconocen el derecho vulnerado y adoptan las medidas oportunas para su restablecimiento.',c:'Condenan al funcionario responsable.',d:'Obligan al Parlamento a modificar la ley.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:100, q:'¿Qué se entiende por tutela cautelar en el proceso?', o:{a:'La medida adoptada por el Juez para asegurar la efectividad de la sentencia que se dicte.',b:'El recurso previo a la sentencia.',c:'La asistencia jurídica gratuita.',d:'La suspensión del proceso.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:101, q:'El CGPJ ejerce sus competencias en materia de:', o:{a:'Nombramiento, ascensos, inspección y régimen disciplinario de Jueces y Magistrados.',b:'Elaboración de leyes procesales.',c:'Dirección de la Administración de Justicia.',d:'Control de la legalidad de las resoluciones judiciales.'}, correct:'b', why:{b:'El art.122.2 CE y la LOPJ atribuyen al CGPJ las funciones de nombramiento, ascensos, inspección y régimen disciplinario de Jueces y Magistrados.'}},
{n:102, q:'¿Ante qué órgano se interpone el recurso de revisión penal?', o:{a:'El Juzgado de lo Penal.',b:'La Audiencia Provincial.',c:'La Sala de lo Penal del Tribunal Supremo.',d:'El Tribunal Constitucional.'}, correct:'c', why:{c:'El recurso de revisión penal, dirigido a rescindir sentencias firmes injustas, se interpone ante la Sala de lo Penal del Tribunal Supremo, conforme a la Ley de Enjuiciamiento Criminal.'}},
{n:103, q:'Las demandas de amparo constitucional deben interponerse en el plazo de:', o:{a:'15 días.',b:'20 días.',c:'30 días.',d:'3 meses.'}, correct:'c', why:{c:'La LOTC establece que el recurso de amparo deberá interponerse dentro del plazo de treinta días, a partir de la notificación de la resolución recaída en el proceso judicial previo.'}},
{n:104, q:'¿Qué es el error judicial?', o:{a:'Cualquier resolución que perjudique al ciudadano.',b:'El daño causado por resoluciones judiciales injustas o dictadas con dolo o culpa grave, que da derecho a indemnización.',c:'Un recurso extraordinario.',d:'La responsabilidad disciplinaria del Juez.'}, correct:'d', why:{d:'El error judicial es la equivocación manifiesta e inexcusable de un órgano judicial al aplicar la ley, que puede dar lugar a responsabilidad del Estado conforme al art.121 CE y a indemnización al perjudicado.'}},
{n:105, q:'El art.121 CE reconoce el derecho a ser indemnizado por los daños causados por:', o:{a:'Solo por sentencias injustas.',b:'El funcionamiento anormal de la Administración de Justicia.',c:'Los errores del Ministerio de Justicia.',d:'Los errores del Ministerio Fiscal.'}, correct:'c', why:{c:'El art.121 CE establece que los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado.'}},
{n:106, q:'El Tribunal Constitucional conoce de los conflictos en defensa de la autonomía local, que pueden ser planteados por:', o:{a:'Un Ayuntamiento.',b:'Un número de Municipios que representen al menos un séptimo de los existentes en el ámbito territorial de aplicación de la ley.',c:'Las respuestas a y b son correctas.',d:'Solo el Gobierno del Estado.'}, correct:'c', why:{c:'La LOTC, tras su reforma, reconoce a los municipios y provincias legitimación para plantear conflictos en defensa de la autonomía local: un municipio individualmente o un número que represente al menos un séptimo de los afectados.'}},
{n:107, q:'El principio de proporcionalidad en el Derecho Procesal:', o:{a:'Exige que la sanción sea proporcional a la infracción.',b:'Impide que las medidas cautelares causen perjuicios desproporcionados.',c:'Solo se aplica en el proceso penal.',d:'Solo lo aplica el Tribunal Constitucional.'}, correct:'c', why:{c:'El principio de proporcionalidad tiene aplicación en todos los órdenes jurisdiccionales, especialmente en materia de medidas cautelares, limitación de derechos y sanciones.'}},
{n:108, q:'La Sala de lo Civil del Tribunal Supremo conoce de:', o:{a:'Los recursos de casación en materia civil y los conflictos de competencia entre tribunales.',b:'Solo los recursos de casación.',c:'Los asuntos civiles en primera instancia.',d:'Los recursos de revisión en materia penal.'}, correct:'d', why:{d:'La Sala de lo Civil del Tribunal Supremo conoce de los recursos de casación, extraordinario por infracción procesal y revisión en materia civil, así como de otros asuntos previstos en la ley.'}},
{n:109, q:'Según la CE, la justicia es gratuita en todo caso para:', o:{a:'Los desempleados.',b:'Quienes acrediten insuficiencia de recursos.',c:'Todos los ciudadanos.',d:'Solo los imputados en proceso penal.'}, correct:'c', why:{c:'El art.119 CE establece que la justicia será gratuita cuando así lo disponga la ley, y en todo caso respecto de quienes acrediten insuficiencia de recursos para litigar.'}},
{n:110, q:'¿Ante qué Sala del Tribunal Supremo se ventilan los recursos contencioso-administrativos contra actos del Gobierno?', o:{a:'Sala Primera (Civil).',b:'Sala Segunda (Penal).',c:'Sala Tercera (Contencioso-Administrativo).',d:'Sala Cuarta (Social).'}, correct:'d', why:{d:'La Sala Tercera del Tribunal Supremo (de lo Contencioso-Administrativo) es competente para conocer de los recursos contra actos del Gobierno y sus miembros.'}},
{n:111, q:'¿En qué momento procesal se practica la prueba en el proceso civil?', o:{a:'En la fase de alegaciones.',b:'En el acto de la vista o juicio oral.',c:'Tras la sentencia.',d:'En cualquier momento del proceso.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:112, q:'¿Puede el Tribunal Constitucional conocer de cuestiones de legalidad ordinaria?', o:{a:'Sí, siempre que lo solicite el Gobierno.',b:'No, solo conoce de cuestiones constitucionales.',c:'Sí, pero solo en materia penal.',d:'Sí, cuando así lo pida el CGPJ.'}, correct:'b', why:{b:'El Tribunal Constitucional solo conoce de cuestiones constitucionales, no de legalidad ordinaria; la interpretación y aplicación de la ley ordinaria corresponde a los tribunales ordinarios.'}},
{n:113, q:'El principio de instancia única en el proceso penal significa:', o:{a:'Que no caben recursos.',b:'Que la sentencia de primera instancia es inapelable.',c:'Que los juicios orales se celebran ante un único juez.',d:'Que el recurso de apelación solo procede en determinados casos.'}, correct:'a', why:{a:'El principio de instancia única en el proceso penal histórico significaba que la sentencia de primera instancia era inapelable, aunque actualmente el sistema ha evolucionado.'}},
{n:114, q:'Las Salas de lo Civil y Penal de los Tribunales Superiores de Justicia conocen de:', o:{a:'Los recursos de casación en materia de derecho civil foral o especial propio de la Comunidad Autónoma.',b:'Todos los recursos civiles de la CCAA.',c:'Solo los conflictos entre municipios.',d:'Los recursos contra resoluciones del Gobierno autonómico.'}, correct:'a', why:{a:'Las Salas de lo Civil y Penal de los TSJ conocen de los recursos de casación en materia de derecho civil foral o especial propio de la Comunidad Autónoma.'}},
{n:115, q:'El Ministerio Fiscal ejerce sus funciones respetando siempre:', o:{a:'Las instrucciones del Gobierno.',b:'Los principios de legalidad e imparcialidad.',c:'Las directrices del CGPJ.',d:'Las órdenes del Ministro de Justicia.'}, correct:'b', why:{b:'El art.124.2 CE establece que el Ministerio Fiscal ejerce sus funciones con sujeción a los principios de legalidad e imparcialidad, además de los de unidad de actuación y dependencia jerárquica interna.'}},
{n:116, q:'El recurso de apelación en el proceso civil es resuelto por:', o:{a:'El Tribunal Supremo.',b:'El Tribunal Superior de Justicia.',c:'La Audiencia Provincial.',d:'El Juzgado de Primera Instancia.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:117, q:'El Defensor del Pueblo puede supervisar la actividad de:', o:{a:'Solo la Administración del Estado.',b:'La Administración del Estado, autonómica y local.',c:'Solo los órganos constitucionales.',d:'Solo el Poder Ejecutivo.'}, correct:'c', why:{c:'El art.54 CE establece que el Defensor del Pueblo es el alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos del Título I, pudiendo supervisar la actividad de las Administraciones.'}},
{n:118, q:'¿Cuántos magistrados propone el Senado para el Tribunal Constitucional?', o:{a:'2.',b:'4.',c:'6.',d:'8.'}, correct:'b', why:{b:'El art.159.1 CE establece que el Senado propone cuatro de los doce magistrados del Tribunal Constitucional.'}},
{n:119, q:'El proceso penal en España es fundamentalmente:', o:{a:'Acusatorio y oral.',b:'Inquisitivo y escrito.',c:'Mixto (inquisitivo en la instrucción y acusatorio en el juicio oral).',d:'Solo oral.'}, correct:'b', why:{b:'El proceso penal español es de tipo mixto: la fase de instrucción es predominantemente inquisitiva (el Juez investiga de oficio) y la fase de juicio oral es acusatoria (rige el principio acusatorio y la oralidad).'}},
{n:120, q:'El auto de procesamiento en el proceso penal:', o:{a:'Es la resolución que inicia el proceso.',b:'Es la resolución que dirige el proceso contra una persona determinada.',c:'Es la sentencia de primera instancia.',d:'Es el recurso de apelación.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:121, q:'Las sentencias del Tribunal Constitucional que declaren la inconstitucionalidad de una ley:', o:{a:'Son definitivas e inapelables.',b:'Tienen efectos solo para las partes del proceso.',c:'Pueden ser recurridas ante el Tribunal Supremo.',d:'Tienen efectos retroactivos ilimitados.'}, correct:'b', why:{b:'Las sentencias del TC son definitivas e inapelables (art.164.1 CE); no pueden ser recurridas ante ningún otro tribunal español, aunque sí pueden ser objeto de recurso ante el TJUE o el TEDH si afectan a derechos del Convenio Europeo.'}},
{n:122, q:'El Consejo General del Poder Judicial aprueba el nombramiento de los Presidentes de las Audiencias Provinciales, Tribunales Superiores de Justicia y Audiencia Nacional mediante:', o:{a:'Decreto del Gobierno.',b:'Acuerdo del Pleno del CGPJ.',c:'Propuesta del Ministerio de Justicia.',d:'Resolución del Tribunal Supremo.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:123, q:'El principio de ne bis in idem prohíbe:', o:{a:'Juzgar a una persona dos veces por los mismos hechos.',b:'Dictar dos sentencias en el mismo proceso.',c:'Que un Juez conozca dos causas distintas del mismo acusado.',d:'Que el Ministerio Fiscal actúe en más de un proceso.'}, correct:'b', why:{b:'El principio de ne bis in idem prohíbe juzgar a una persona dos veces por los mismos hechos, garantía reconocida en el art.25.1 CE y en el Protocolo 7 del CEDH.'}},
{n:124, q:'La Audiencia Provincial es competente en materia penal para conocer de:', o:{a:'Faltas y delitos leves.',b:'Delitos castigados con pena superior a cinco años de prisión, juzgados en primera instancia.',c:'Solo delitos contra la propiedad.',d:'Recursos de apelación contra autos de los Juzgados de Instrucción y sentencias de los Juzgados de lo Penal.'}, correct:'d', why:{d:'La Audiencia Provincial conoce en materia penal de los recursos de apelación contra autos y sentencias de los Juzgados de Instrucción y de los Juzgados de lo Penal.'}},
{n:125, q:'¿Cuántos magistrados propone el Gobierno para el Tribunal Constitucional?', o:{a:'1.',b:'2.',c:'3.',d:'4.'}, correct:'a', why:{a:'El art.159.1 CE establece que el Gobierno propone dos de los doce magistrados del Tribunal Constitucional.'}},
{n:126, q:'El principio de independencia judicial implica que los Jueces:', o:{a:'No pueden ser investigados penalmente.',b:'Solo están sometidos al imperio de la ley y no reciben instrucciones de ningún poder.',c:'Pueden ignorar las sentencias del Tribunal Supremo.',d:'Son inamovibles en su destino.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:127, q:'El recurso de queja en el proceso civil procede cuando:', o:{a:'La parte considera injusta la sentencia.',b:'El tribunal de instancia rechaza la admisión de un recurso de apelación o casación.',c:'El Juez rechaza una prueba pertinente.',d:'La ejecución de la sentencia se dilata indebidamente.'}, correct:'c', why:{c:'El recurso de queja procede cuando el tribunal inferior deniega la admisión de un recurso de apelación, casación o infracción procesal, permitiendo que el tribunal superior revise dicha decisión.'}},
{n:128, q:'¿Qué resolución pone fin al proceso penal sin condena ni absolución?', o:{a:'El sobreseimiento.',b:'La absolución.',c:'El auto de archivo.',d:'La prescripción.'}, correct:'b', why:{b:'El sobreseimiento es la resolución judicial que pone fin al proceso penal sin dictar sentencia condenatoria ni absolutoria, por razones procesales (sobreseimiento libre) o por insuficiencia de pruebas (sobreseimiento provisional).'}},
{n:129, q:'El Tribunal Constitucional puede conocer de conflictos entre órganos constitucionales del Estado. ¿Cuáles pueden plantear dichos conflictos?', o:{a:'El Congreso, el Senado, el Gobierno y el CGPJ.',b:'Solo el Congreso y el Gobierno.',c:'Solo el Tribunal Supremo y el Gobierno.',d:'Cualquier órgano del Estado.'}, correct:'c', why:{c:'Los conflictos entre órganos constitucionales del Estado pueden ser planteados ante el TC por el Congreso, el Senado, el Gobierno y el CGPJ conforme a la LOTC.'}},
{n:130, q:'¿Cuántos magistrados propone el Congreso de los Diputados para el Tribunal Constitucional?', o:{a:'2.',b:'4.',c:'6.',d:'8.'}, correct:'c', why:{c:'El art.159.1 CE establece que el Congreso de los Diputados propone cuatro de los doce magistrados del Tribunal Constitucional.'}},
];
